_handleUpdateFail() {
  // Retry sooner to get updates as soon as possible but back off if the
  // failure continues following the fallbackIntervals.
  this._schedule(
    this._fallbackIntervals[
      Math.min(this._failureCount, this._fallbackIntervals.length - 1)
    ]
  );
  this._failureCount++;
},

_schedule(time) {
  if (this._timeout) {
    lazy.console.warn("update already scheduled");
    return;
  }
  this._timeout = lazy.setTimeout(() => {
    this._timeout = null;

    this._fetch();
  }, time);
},

/**
 * Utility for tests that resets the state, including failure counts, history
 * and pending scheduled updates.
 */
_clearStateForTests() {
  this._failureCount = 0;
  this._updateHistory.length = 0;
  if (!this._timeout) {
    return;
  }
  lazy.clearTimeout(this._timeout);
  this._timeout = null;
},
